    TwistSquash::SquashKeyA(CASTOR_KEY_A_H_IceLaneA, CASTOR_KEY_A_H_IceLaneB, CASTOR_KEY_A_H_IceLaneC, CASTOR_KEY_A_H_IceLaneD, &(pWorkSpace->mKeyBoxA[7U][0]));

    aIngress = *pIngress;
    aCarry = *pCarry;
    aWandererA = *pWandererA;
    aWandererB = *pWandererB;
    aWandererC = *pWandererC;
    aWandererD = *pWandererD;
    aWandererE = *pWandererE;
    aWandererF = *pWandererF;
    aWandererG = *pWandererG;
    aWandererH = *pWandererH;
    aWandererI = *pWandererI;
    aWandererJ = *pWandererJ;
    aWandererK = *pWandererK;

    // Key flow — B / A

    //
    // src: [$earth, $crystal]
    // dst: [$arcane]
    //
    TwistExpander_Castor_Arx::KEY_B_A_A(PARAMS_SEED);

    //
