    //
    // src: [$arcane]
    // dst: [$plasma]
    //
    TwistExpander_Castor_Arx::KEY_B_G_B(PARAMS_SEED);

    KeyDiffuse_A_B_G(pWorkSpace);

    //
    // src: [$rainbow]
    // dst: [$water]
    //
    TwistExpander_Castor_Arx::KEY_B_G_C(PARAMS_SEED);

    //
    // src: [$water]
    // dst: [$vapor]
    //
    TwistExpander_Castor_Arx::KEY_B_G_D(PARAMS_SEED);

    KeyDiffuse_B_B_G(pWorkSpace);

    //
    // src: [$frost]
    // dst: [$ice]
    //
    TwistExpander_Castor_Arx::KEY_B_G_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(CASTOR_KEY_B_G_IceLaneA, CASTOR_KEY_B_G_IceLaneB, CASTOR_KEY_B_G_IceLaneC, CASTOR_KEY_B_G_IceLaneD, &(pWorkSpace->mKeyBoxB[6U][0]));

    // Key flow — B / H

    //
    // src: [$earth, $crystal]
    // dst: [$arcane]
