    //
    // src: [$arcane]
    // dst: [$plasma]
    //
    TwistExpander_Castor_Arx::KEY_B_H_B(PARAMS_SEED);

    KeyDiffuse_A_B_H(pWorkSpace);

    //
    // src: [$rainbow]
    // dst: [$water]
    //
    TwistExpander_Castor_Arx::KEY_B_H_C(PARAMS_SEED);
    //
    // src: [$water]
    // dst: [$vapor]
    //
    TwistExpander_Castor_Arx::KEY_B_H_D(PARAMS_SEED);

    KeyDiffuse_B_B_H(pWorkSpace);

    //
    // src: [$frost]
    // dst: [$ice]
    //
